UPDATE COURSE_HOMEWORK
   SET CONTENT  = #{modifyHomeworkVO.content}
     , END_DATE = #{modifyHomeworkVO.endDate}
     , MDFY_DT  = SYSDATE
 WHERE COURSE_ID = #{courseId}
   AND ID        = #{homeworkId}
   AND DEL_YN    = 'N'

UPDATE COURSE_HOMEWORK_REPLY
   SET CONTENT = #{content}
     , MDFY_DT = SYSDATE
 WHERE ID                = #{id}
   AND HOMEWORK_ID       = #{homeworkId}
   AND COURSE_STUDENT_ID = #{courseStudentId}
   AND DEL_YN            = 'N'

UPDATE COURSE_HOMEWORK
   SET DEL_YN  = 'Y'
     , MDFY_DT = SYSDATE
 WHERE COURSE_ID = #{courseId}
   AND ID        = #{homeworkId}
   AND DEL_YN    = 'N'

UPDATE COURSE_HOMEWORK_REPLY
   SET DEL_YN  = 'Y'
     , MDFY_DT = SYSDATE
 WHERE ID          = #{replyId}
   AND HOMEWORK_ID = #{homeworkId}
   AND DEL_YN      = 'N'

